code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find a full divider made of color 2.
    divider = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            divider = ("h", r)
            break
    if divider is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                divider = ("v", c)
                break
    if divider is None:
        return out
    axis, pos = divider
    bg = grid[0][0]
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, 2)]
    if not cells:
        return out
    # The colored object is translated toward the divider as one pattern.
    rmin = min(r for r, c in cells); rmax = max(r for r, c in cells)
    cmin = min(c for r, c in cells); cmax = max(c for r, c in cells)
    if axis == "v":
        # The object lies on one side of the vertical divider.
        if cmin > pos:
            shift = pos + 1 - cmin
            far = cmax + shift + 1
        elif cmax < pos:
            shift = pos - 1 - cmax
            far = cmin + shift - 1
        else:
            return out
        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            nc = c + shift
            if 0 <= nc < w:
                out[r][nc] = grid[r][c]
        if 0 <= far < w:
            for r in range(h):
                out[r][far] = 8
    else:
        if rmin > pos:
            shift = pos + 1 - rmin
            far = rmax + shift + 1
        elif rmax < pos:
            shift = pos - 1 - rmax
            far = rmin + shift - 1
        else:
            return out
        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            nr = r + shift
            if 0 <= nr < h:
                out[nr][c] = grid[r][c]
        if 0 <= far < h:
            for c in range(w):
                out[far][c] = 8
    return out
'''
